import org.apache.tika.sax.BasicContentHandlerFactory;
import org.apache.tika.parser.ParseContext;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;
import java.util.Locale;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class BasicContentHandlerFactoryTest {

    @Mock
    private ParseContext parseContext;

    private BasicContentHandlerFactory factory;

    @BeforeEach
    public void setUp() {
        factory = new BasicContentHandlerFactory();
    }

    @Test
    public void testParseHandlerType_withNullHandlerTypeName() {
        String handlerTypeName = null;
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(defaultType, result);
    }

    @Test
    public void testParseHandlerType_withValidHandlerTypeName() {
        String handlerTypeName = "xml";
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(BasicContentHandlerFactory.HANDLER_TYPE.XML, result);
    }

    @Test
    public void testParseHandlerType_withInvalidHandlerTypeName() {
        String handlerTypeName = "invalid";
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(defaultType, result);
    }
}
